import { useEffect, useState } from 'react';

// Goal names and icon recipes, generated by scripts/import-goals.mjs from the tier-guide build.
export interface Goal {
  c: 'item' | 'advancement' | 'challenge';
  k?: string;            // advancement tab, or challenge kind: collect / never / stat / all / any
  t: string;
  n: string;
  z?: string;
  d?: string;
  zd?: string;
  i?: string;            // item to draw
  s?: 'one' | 'all';     // composite icon: "any of" stack or "all of" grid
  ii?: string[];         // items in the composite
  img?: string;          // the mod's own picture for this goal
  x?: 1;                 // "never get X": forbidden frame on top
  g?: string;            // mutually exclusive group on the normal board: at most one per card
  st?: string;           // tier on the simplified board (absent: not on that board)
  sg?: string;           // exclusive group on the simplified board
  sm?: 1;                // only exists on the simplified board ("Any X")
  draft?: 1;             // goal from Bingout's Draftout pool
}
export type Goals = Record<string, Goal>;

// must match iconFile in scripts/import-goals.mjs
export const iconFile = (key: string) => key.replace(/[^a-z0-9_-]/gi, '_') + '.png';

let index: Promise<string[]> | null = null;
const cache = new Map<string, Promise<Goals>>();

/** YAB reports "2.15.1+mc26.3"; goal files are kept per mod release ("2.15.1"). */
async function resolveVersion(modVersion: string) {
  index ??= fetch('/goals/index.json').then(r => r.json()).then(j => j.versions as string[]);
  const versions = await index;
  const base = modVersion.split('+')[0];
  const release = base.replace(/-build\.[\w.-]+$/, '');
  // an unknown release falls back to the newest data we have; most goals carry over between releases
  return versions.includes(base) ? base : versions.includes(release) ? release : versions[versions.length - 1];
}

export function loadGoals(modVersion: string) {
  return resolveVersion(modVersion).then(v => {
    if (!cache.has(v)) cache.set(v, fetch(`/goals/${v}/goals.json`).then(r => r.json()));
    return cache.get(v)!.then(goals => ({ version: v, goals }));
  });
}

export function useGoals(modVersion: string | undefined) {
  const [state, setState] = useState<{ version: string; goals: Goals } | null>(null);
  useEffect(() => {
    if (!modVersion) return;
    let live = true;
    loadGoals(modVersion).then(s => live && setState(s)).catch(() => live && setState({ version: '', goals: {} }));
    return () => { live = false; };
  }, [modVersion]);
  return state;
}

/** "minecraft:story/mine_stone" → "Mine Stone", for goals the data doesn't know. */
export const prettyId = (id: string) =>
  id.split(/[:/]/).pop()!.replace(/^one_of_/, 'any ').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
